using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using System.Text.RegularExpressions;
using Rhino;
using Rhino.PlugIns;
using Rhino.UI;
using Skunk.Core;

namespace Skunk.UI
{
    /// <summary>
    /// The Skunk toolbar: Skunk.rui, embedded in the engine (generated by tools/gen_project.py) and written by Skunk to
    /// the one place Rhino opens it from.
    /// <para>
    /// Rhino 9 opens the toolbar files named in its window layout at start-up, before it builds the toolbar containers,
    /// so a toolbar the user docked into a container of their own (a tab in another toolbar) stays there only when its
    /// file is open by then. A toolbar file shipped beside the plug-in is the plug-in's own: Rhino opens it only when the
    /// plug-in loads, after the containers. Up to 1.6.5 every package carried one, and it had the same file id as the copy
    /// Skunk kept in the package folder: when Skunk loaded, Rhino took the package's file in place of the copy, Skunk
    /// closed it - taking the toolbar out of the user's container - and opened its copy, which Rhino showed floating. So
    /// since 1.6.6 no package carries a toolbar file. Skunk writes its own once - into the package folder
    /// (packages\9.0\Skunk\Skunk.rui, beside Yak's manifest.txt: updates leave it, an uninstall removes it; beside the
    /// plug-in in a development build) - and opens it when no toolbar file holds the Skunk group. Rhino's layout then
    /// names it like any toolbar file of the user's and opens it with Rhino. A new version rewrites it only when its
    /// buttons changed, keeping its file id.
    /// </para>
    /// </summary>
    public static class SkunkToolbar
    {
        /// <summary>Skunk's plug-in id (the Script Editor project id; the compiled plug-in uses the same).</summary>
        public static readonly Guid PlugInId = new Guid("f13025f7-108d-504b-80fb-7ff84ca963ea");

        /// <summary>The toolbar group id tools/gen_project.py writes into Skunk.rui (checked by SkunkCheck rui).</summary>
        public static readonly Guid GroupId = new Guid("c879d7c5-a20d-50fc-9afe-ae95427fd409");

        /// <summary>The toolbar file's name.</summary>
        public const string FileName = "Skunk.rui";

        /// <summary>Beside the toolbar file: what its buttons are (a hash), to tell when a new version changed them.</summary>
        public const string StampName = "Skunk.rui.version";

        /// <summary>The toolbar embedded in Skunk.Core (and compiled into the always-on plug-in).</summary>
        public const string Resource = "Skunk.Core.Resources.Skunk.rui";

        static bool s_checked;

        /// <summary>
        /// Once a session (the first Skunk command; the compiled plug-in when Rhino starts): write the toolbar where Rhino
        /// opens it and open it when no toolbar file holds it. Says so on the command line only when it changed something.
        /// </summary>
        public static void CheckOnce()
        {
            if (s_checked)
                return;
            s_checked = true;
            try
            {
                string done = Ensure(PlugInPath(), Embedded(), new RhinoToolbarHost(), new RhinoToolbarRecord());
                if (done != null)
                    Log.Info(done);
            }
            catch (Exception ex)
            {
                Log.Warn("the Skunk toolbar was not set up (" + ex.GetType().Name + ": " + ex.Message + ").");
            }
        }

        /// <summary>The embedded toolbar file, or null.</summary>
        public static byte[] Embedded()
        {
            using (var s = typeof(SkunkToolbar).Assembly.GetManifestResourceStream(Resource))
            {
                if (s == null)
                    return null;
                using (var m = new MemoryStream())
                {
                    s.CopyTo(m);
                    return m.ToArray();
                }
            }
        }

        /// <summary>Where the toolbar file lives for the plug-in file <paramref name="rhp"/>: the package folder, or beside it.</summary>
        public static string Target(string rhp, Func<string, bool> exists)
        {
            var place = PackagePlace.Of(rhp, exists);
            return place != null ? place.StableFile : Path.Combine(Path.GetDirectoryName(rhp) ?? "", FileName);
        }

        /// <summary>
        /// The work of <see cref="CheckOnce"/> for the plug-in file <paramref name="rhp"/> and the toolbar file's contents,
        /// with Rhino's toolbars and its record of Skunk's toolbar file passed in (SkunkCheck runs it on temporary folders with
        /// stand-ins, never on Rhino's). Null when nothing changed, else a line for the command line.
        /// </summary>
        public static string Ensure(string rhp, byte[] toolbar, IToolbarHost host, IToolbarRecord record)
        {
            if (string.IsNullOrEmpty(rhp) || toolbar == null || toolbar.Length == 0)
                return null;
            string target = Target(rhp, File.Exists);
            string stamp = Path.Combine(Path.GetDirectoryName(target) ?? "", StampName);
            string key = Hash(Buttons(toolbar));
            bool exists = File.Exists(target);
            bool current = exists && (ReadStamp(stamp) == key || Hash(Buttons(File.ReadAllBytes(target))) == key);
            var open = host.OpenFiles();
            // as it was before: a toolbar reopened with new buttons stays where the user had it
            bool show = ShowAfterOpen(open.Count > 0, host.Shown());
            var plan = Plan(exists, current, open, target);
            foreach (var path in plan.Close)
                host.Close(path);
            if (plan.Write)
                File.WriteAllBytes(target, KeepFileId(toolbar, exists ? File.ReadAllBytes(target) : null));
            if (File.Exists(target) && ReadStamp(stamp) != key)
                File.WriteAllText(stamp, key);
            bool opened = plan.Open && host.Open(target, show);
            // Rhino opens a plug-in's own toolbar file late, when the plug-in loads: Skunk has none
            if (!string.IsNullOrEmpty(record.Get()))
                record.Set("");
            if (plan.Open && !opened)
                return "the Skunk toolbar did not open: open " + target + " with Toolbars > File > Open.";
            if (plan.Write)
                return exists ? "the Skunk toolbar has this version's buttons." : "the Skunk toolbar now opens with Rhino from " + target + ".";
            return plan.Open ? "the Skunk toolbar is back." : null;
        }

        /// <summary>
        /// What <see cref="Ensure"/> does: write the toolbar file when it is missing or its buttons changed; close every other
        /// toolbar file that holds the Skunk group (an older package's own toolbar, a development build's) and the file
        /// itself when it is rewritten (Rhino writes an open toolbar back when it closes); open it when it is not open.
        /// </summary>
        public static ToolbarPlan Plan(bool exists, bool current, IList<string> open, string target)
        {
            var plan = new ToolbarPlan { Write = !exists || !current };
            bool keep = false;
            foreach (var path in open ?? Array.Empty<string>())
            {
                if (!plan.Write && !keep && SamePath(path, target))
                    keep = true;
                else
                    plan.Close.Add(path);
            }
            plan.Open = !keep;
            return plan;
        }

        /// <summary>
        /// Show the Skunk toolbar's own container after opening its file? Yes when no toolbar file held it before (it was
        /// lost); when one did, only if its container was showing. Rhino tells only whether that container shows, not
        /// whether the toolbar is a tab in another one, so a loaded toolbar is never made visible: it would show a second
        /// Skunk toolbar (Rhino names it "Skunk 01") beside the one docked where the user put it.
        /// </summary>
        public static bool ShowAfterOpen(bool loaded, bool shown) => !loaded || shown;

        /// <summary>What a toolbar's buttons are: their macros and texts, sorted (Rhino's own re-save of the file keeps them).</summary>
        public static string Buttons(byte[] rui)
        {
            var text = Encoding.UTF8.GetString(rui ?? Array.Empty<byte>());
            var parts = Regex.Matches(text, "<(script|locale_1033)>(.*?)</\\1>", RegexOptions.Singleline)
                .Cast<Match>()
                .Select(m => m.Groups[1].Value + ":" + m.Groups[2].Value.Trim())
                .OrderBy(s => s, StringComparer.Ordinal);
            return string.Join("\n", parts);
        }

        static string Hash(string text)
        {
            using (var sha = SHA256.Create())
                return BitConverter.ToString(sha.ComputeHash(Encoding.UTF8.GetBytes(text))).Replace("-", "").Substring(0, 32);
        }

        static string ReadStamp(string path)
        {
            try
            {
                return File.Exists(path) ? File.ReadAllText(path).Trim() : "";
            }
            catch (IOException)
            {
                return "";
            }
        }

        /// <summary>The file id of a toolbar file (its RhinoUI guid), or null.</summary>
        public static string FileId(byte[] rui)
        {
            if (rui == null)
                return null;
            var m = Regex.Match(Encoding.UTF8.GetString(rui), "<RhinoUI\\b[^>]*?\\sguid=\"([^\"]*)\"");
            return m.Success ? m.Groups[1].Value : null;
        }

        /// <summary>The new toolbar with the file id of the one it replaces, so Rhino's layout still knows it.</summary>
        static byte[] KeepFileId(byte[] toolbar, byte[] old)
        {
            string id = FileId(old);
            if (string.IsNullOrEmpty(id))
                return toolbar;
            var text = Encoding.UTF8.GetString(toolbar);
            var m = Regex.Match(text, "<RhinoUI\\b[^>]*?\\sguid=\"([^\"]*)\"");
            if (!m.Success)
                return toolbar;
            var g = m.Groups[1];
            return Encoding.UTF8.GetBytes(text.Substring(0, g.Index) + id + text.Substring(g.Index + g.Length));
        }

        /// <summary>
        /// The Skunk command (also a start-up command): make sure the Skunk toolbar is loaded. When a toolbar file holds it,
        /// nothing changes - it shows where the user put it, or stays hidden; otherwise Skunk's toolbar file is opened and
        /// shown. False when there is none.
        /// </summary>
        public static bool Load(out string path, out bool opened)
        {
            path = "";
            opened = false;
            var file = Find();
            if (file == null)
            {
                string rhp = PlugInPath();
                file = string.IsNullOrEmpty(rhp) ? null : OpenFile(Target(rhp, File.Exists));
                var group = Group(file);
                if (group == null)
                    return false;
                if (!group.Visible)
                    group.Visible = true;
                opened = true;
            }
            path = file.Path ?? "";
            return true;
        }

        /// <summary>The open toolbar file that holds the Skunk toolbar group, or null.</summary>
        public static ToolbarFile Find()
        {
            var files = RhinoApp.ToolbarFiles;
            for (int i = 0; files != null && i < files.Count; i++)
                if (Group(files[i]) != null)
                    return files[i];
            return null;
        }

        /// <summary>The same file, compared as full paths without regard to case.</summary>
        public static bool SamePath(string a, string b)
        {
            if (string.IsNullOrEmpty(a) || string.IsNullOrEmpty(b))
                return false;
            try
            {
                return string.Equals(Path.GetFullPath(a).TrimEnd('\\', '/'), Path.GetFullPath(b).TrimEnd('\\', '/'),
                                     StringComparison.OrdinalIgnoreCase);
            }
            catch (Exception)
            {
                return string.Equals(a, b, StringComparison.OrdinalIgnoreCase);
            }
        }

        internal static ToolbarGroup Group(ToolbarFile file)
        {
            for (int i = 0; file != null && i < file.GroupCount; i++)
            {
                var g = file.GetGroup(i);
                if (g != null && g.Id == GroupId)
                    return g;
            }
            return null;
        }

        static string PlugInPath()
        {
            try
            {
                return PlugIn.PathFromId(PlugInId);
            }
            catch (Exception)
            {
                return null;
            }
        }

        static ToolbarFile OpenFile(string path) =>
            !string.IsNullOrEmpty(path) && File.Exists(path) ? RhinoApp.ToolbarFiles.Open(path) : null;
    }

    /// <summary>What <see cref="SkunkToolbar.Ensure"/> does: close these toolbar files, write, open.</summary>
    public sealed class ToolbarPlan
    {
        /// <summary>Toolbar files to close first.</summary>
        public readonly List<string> Close = new List<string>();

        /// <summary>Write the toolbar file (it is missing, or its buttons changed).</summary>
        public bool Write;

        /// <summary>Open the toolbar file (Rhino shows it).</summary>
        public bool Open;
    }

    /// <summary>
    /// Where a Yak install keeps Skunk: ...\packages\9.0\Skunk\{version}\Skunk.rhp, with Yak's manifest.txt in the
    /// package folder.
    /// </summary>
    public sealed class PackagePlace
    {
        public string VersionFolder;
        public string PackageFolder;

        /// <summary>The version folder's name (the package version).</summary>
        public string Version;

        /// <summary>Skunk's toolbar file, in the package folder (updates leave it, an uninstall removes it).</summary>
        public string StableFile => Path.Combine(PackageFolder, SkunkToolbar.FileName);

        public string StampFile => Path.Combine(PackageFolder, SkunkToolbar.StampName);

        /// <summary>The place of a plug-in file, or null when it is not in a Yak package (a development build).</summary>
        public static PackagePlace Of(string rhp, Func<string, bool> exists)
        {
            if (string.IsNullOrEmpty(rhp))
                return null;
            string version = Path.GetDirectoryName(rhp);
            string package = string.IsNullOrEmpty(version) ? null : Path.GetDirectoryName(version);
            if (string.IsNullOrEmpty(package) || !exists(Path.Combine(package, "manifest.txt")))
                return null;
            return new PackagePlace { VersionFolder = version, PackageFolder = package, Version = Path.GetFileName(version) };
        }
    }

    /// <summary>Rhino's open toolbar files, as far as the Skunk toolbar goes.</summary>
    public interface IToolbarHost
    {
        /// <summary>Paths of the open toolbar files that hold the Skunk toolbar group.</summary>
        IList<string> OpenFiles();

        /// <summary>Close that toolbar file (Rhino takes it out of its layout; the file stays on disk).</summary>
        void Close(string path);

        /// <summary>Open a toolbar file, showing the Skunk group's own container when asked; false when Rhino did not open it.</summary>
        bool Open(string path, bool show);

        /// <summary>The Skunk group's own toolbar container is showing.</summary>
        bool Shown();
    }

    /// <summary>
    /// Rhino's record of a plug-in's own toolbar file: the RuiFile value of its plug-in entry. Skunk has none (its toolbar
    /// is a toolbar file like the user's, see <see cref="SkunkToolbar"/>), so Skunk clears it.
    /// </summary>
    public interface IToolbarRecord
    {
        string Get();

        void Set(string path);
    }

    /// <summary>The Skunk toolbar in Rhino's own toolbar files.</summary>
    public sealed class RhinoToolbarHost : IToolbarHost
    {
        public IList<string> OpenFiles()
        {
            var list = new List<string>();
            var files = RhinoApp.ToolbarFiles;
            for (int i = 0; files != null && i < files.Count; i++)
                if (SkunkToolbar.Group(files[i]) != null)
                    list.Add(files[i].Path ?? "");
            return list;
        }

        public void Close(string path)
        {
            var files = RhinoApp.ToolbarFiles;
            for (int i = 0; files != null && i < files.Count; i++)
            {
                if (SkunkToolbar.Group(files[i]) != null && SkunkToolbar.SamePath(files[i].Path, path))
                {
                    files[i].Close(false);
                    return;
                }
            }
        }

        public bool Open(string path, bool show)
        {
            var group = SkunkToolbar.Group(RhinoApp.ToolbarFiles.Open(path));
            if (group == null)
                return false;
            if (show && !group.Visible)
                group.Visible = true;
            return true;
        }

        public bool Shown()
        {
            var files = RhinoApp.ToolbarFiles;
            for (int i = 0; files != null && i < files.Count; i++)
                if (SkunkToolbar.Group(files[i])?.Visible == true)
                    return true;
            return false;
        }
    }

    /// <summary>
    /// The record in Rhino's registry entry for Skunk (HKCU\Software\McNeel\Rhinoceros\9.0\Plug-ins\{id}, RuiFile).
    /// Changes the value only in an entry Rhino made. Never used by SkunkCheck: headless Rhino runs on the user's own
    /// settings.
    /// </summary>
    public sealed class RhinoToolbarRecord : IToolbarRecord
    {
        static string Key => @"Software\McNeel\Rhinoceros\" + RhinoApp.ExeVersion + @".0\Plug-ins\" + SkunkToolbar.PlugInId.ToString("D");

        public string Get()
        {
            if (!OperatingSystem.IsWindows())
                return null;
            try
            {
                using (var k = Microsoft.Win32.Registry.CurrentUser.OpenSubKey(Key))
                    return k?.GetValue("RuiFile") as string;
            }
            catch (Exception)
            {
                return null;
            }
        }

        public void Set(string path)
        {
            if (!OperatingSystem.IsWindows())
                return;
            try
            {
                using (var k = Microsoft.Win32.Registry.CurrentUser.OpenSubKey(Key, true))
                    k?.SetValue("RuiFile", path ?? "");
            }
            catch (Exception)
            {
                // the toolbar still opens from Rhino's window layout
            }
        }
    }

    /// <summary>An in-memory record for SkunkCheck.</summary>
    public sealed class MemoryToolbarRecord : IToolbarRecord
    {
        public string Value;

        public string Get() => Value;

        public void Set(string path) => Value = path;
    }
}
